from playwright.sync_api import sync_playwright
import base64,json
from pathlib import Path
JS='''async ({b64,angle})=>{const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0)),dv=new DataView(bytes.buffer),n=dv.getUint32(12,true),j=JSON.parse(new TextDecoder().decode(bytes.slice(20,20+n))),bin=bytes.slice(28+n);const canvas=document.createElement('canvas');canvas.width=390;canvas.height=390;document.body.style.margin='0';document.body.append(canvas);const gl=canvas.getContext('webgl2',{preserveDrawingBuffer:true});if(!gl)throw Error('no webgl2');const shader=(kind,s)=>{let sh=gl.createShader(kind);gl.shaderSource(sh,s);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh));return sh};const pr=gl.createProgram();gl.attachShader(pr,shader(gl.VERTEX_SHADER,`#version 300 es
in vec3 pos;in vec2 uv;out vec2 t;out vec3 p;uniform float a;void main(){vec3 q=vec3(cos(a)*pos.x+sin(a)*pos.z,pos.y,-sin(a)*pos.x+cos(a)*pos.z);p=q;t=uv;gl_Position=vec4(q/0.036,1.);}`));gl.attachShader(pr,shader(gl.FRAGMENT_SHADER,`#version 300 es
precision highp float;in vec2 t;in vec3 p;uniform sampler2D tex;uniform float cut;out vec4 c;void main(){vec4 s=texture(tex,t);if(s.a<cut)discard;vec3 n=normalize(p);c=vec4(s.rgb*(.68+.32*max(dot(n,normalize(vec3(-.3,.6,-1.))),0.)),1.);}`));gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(pr));gl.useProgram(pr);gl.uniform1f(gl.getUniformLocation(pr,'a'),angle);gl.enable(gl.DEPTH_TEST);gl.clearColor(.19,.22,.24,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);function acc(i){let a=j.accessors[i],v=j.bufferViews[a.bufferView];return [a,bin.slice((v.byteOffset||0)+(a.byteOffset||0),(v.byteOffset||0)+v.byteLength)]}let tris=0;for(let m of j.meshes)for(let p of m.primitives){for(let [key,name,size] of [['POSITION','pos',3],['TEXCOORD_0','uv',2]]){let [a,d]=acc(p.attributes[key]);let buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,d,gl.STATIC_DRAW);let l=gl.getAttribLocation(pr,name);gl.enableVertexAttribArray(l);gl.vertexAttribPointer(l,size,a.componentType,false,0,0)}let mat=j.materials[p.material],img=j.images[j.textures[mat.pbrMetallicRoughness.baseColorTexture.index].source],v=j.bufferViews[img.bufferView],bmp=await createImageBitmap(new Blob([bin.slice(v.byteOffset||0,(v.byteOffset||0)+v.byteLength)],{type:img.mimeType}));let tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,bmp);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.uniform1f(gl.getUniformLocation(pr,'cut'),mat.alphaMode==='MASK'?mat.alphaCutoff:0);let [a,d]=acc(p.indices),buf=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,buf);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,d,gl.STATIC_DRAW);gl.drawElements(gl.TRIANGLES,a.count,a.componentType,0);tris+=a.count/3}gl.finish();return {tris,error:gl.getError(),version:gl.getParameter(gl.VERSION),png:canvas.toDataURL('image/png')}}'''
report=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=b.new_page(viewport={'width':390,'height':780});
 for name in ['A-baked','B-shell']:
  for i,angle in enumerate([0,1.1,2.3]):
   page.set_content('<body></body>');r=page.evaluate(JS,dict(b64=base64.b64encode(Path(name+'.glb').read_bytes()).decode(),angle=angle));Path(f'{name}-webgl-{i}.png').write_bytes(base64.b64decode(r.pop('png').split(',')[1]));report.append(dict(name=name,angle=angle,**r))
 b.close()
Path('webgl-report.json').write_text(json.dumps(report,indent=2));print(report)
